/// The contract shared by the server and the clients: an Orsak interface describing the side effect. Its provider and
/// effects, generated by [<GenEffects>], and its proxy, OrderApiProxy, generated by [<GenRemote>], are at the end,
/// written when .NET builds this project; Fable compiles them as they are.
module Remoting.Shared.Contract

open System.Threading
open System.Threading.Tasks
open Orsak
open Orsak.Remoting

type OrderLine = { Product: string; Quantity: int }

type Order = {
    Customer: string
    Lines: OrderLine list
    Note: string option
}

type OrderId = OrderId of int

type PlaceError =
    | EmptyOrder
    | UnknownProduct of string

// [<GenEffects>] is in Orsak.Myriad, which a project referencing its package can use with Fable too, as an attribute
// is compiled to nothing; this project references it as a project, which Fable would compile, so hides it from Fable
/// The side effect: ordering, wherever it happens. On the server, a real implementation; in the client, the remote one.
#if !FABLE_COMPILER
[<Orsak.Myriad.GenEffects>]
#endif
[<GenRemote>]
type IOrderApi =
    abstract Place: Order -> Task<Result<OrderId, PlaceError>>
    // an ASP.NET Core attribute, which MapRemote makes the endpoint's metadata, hidden from Fable, which doesn't have
    // ASP.NET Core
#if !FABLE_COMPILER
    [<Microsoft.AspNetCore.Authorization.AllowAnonymous>]
#endif
    abstract History: customer: string -> Task<Order list>
    // waits until the call is cancelled, which the client does, and Holds counts the calls held and released
    abstract Hold: cancellationToken: CancellationToken -> Task<unit>
    abstract Holds: unit -> Task<int * int>

//------------------------------------------------------------------------------
//        This code was generated by myriad.
//        Changes to this file will be lost when the code is regenerated.
//------------------------------------------------------------------------------
type IOrderApiProvider =
    abstract Effect: IOrderApi

module OrderApi =
    let place a =
        Effect.Create(fun (er: #IOrderApiProvider) -> er.Effect.Place a)

    let history a =
        Effect.Create(fun (er: #IOrderApiProvider) -> er.Effect.History a)

    let hold a =
        Effect.Create(fun (er: #IOrderApiProvider) -> er.Effect.Hold a)

    let holds () =
        Effect.Create(fun (er: #IOrderApiProvider) -> er.Effect.Holds())



module OrderApiProxy =
    let create (client: Orsak.Remoting.RemoteClient) : IOrderApi =
        let place =
            client.Member("IOrderApi", "Place", [| typeof<Order> |], typeof<Result<OrderId, PlaceError>>)

        let history =
            client.Member("IOrderApi", "History", [| typeof<string> |], typeof<Order list>)

        let hold = client.Member("IOrderApi", "Hold", [||], typeof<unit>)
        let holds = client.Member("IOrderApi", "Holds", [||], typeof<int * int>)

        { new IOrderApi with
            member _.Place a = place.Task [| box a |]
            member _.History a = history.Task [| box a |]
            member _.Hold a = hold.Task([||], a)
            member _.Holds() = holds.Task [||]
        }
